INSERT INTO foods (title, description, badge, image, image_alt) VALUES
  ('Pad Krapow Moo', 'Minced pork stir-fried with garlic, chili, and holy basil, served hot over steamed jasmine rice with a fried egg on top.', TRUE, 'https://commons.wikimedia.org/wiki/Special:FilePath/Basil_fried_crispy_pork_with_rice_-_Chiang_Mai_-_2017-07-11_(002).jpg?width=480', 'Stir-fried holy basil pork with rice and a fried egg'),
  ('Tom Yum Goong', 'A fragrant, spicy-and-sour prawn soup simmered with lemongrass, galangal, kaffir lime leaves, chili, and fresh mushrooms.', FALSE, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tom_yam_kung_maenam.jpg?width=480', 'Bowl of tom yum goong prawn soup with lemongrass'),
  ('Green Curry Chicken', 'Tender chicken simmered in a creamy coconut green curry with Thai eggplant, basil, and green chilies for a rich, spicy flavor.', TRUE, 'https://commons.wikimedia.org/wiki/Special:FilePath/Thai_green_chicken_curry_and_roti.jpg?width=480', 'Bowl of green curry chicken served with roti'),
  ('Mango Sticky Rice', 'Sweet coconut sticky rice paired with ripe mango slices, drizzled with coconut cream and a sprinkle of toasted mung beans.', FALSE, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mango_sticy_rice_(3859549574).jpg?width=480', 'Plate of mango sticky rice with coconut cream'),
  ('Som Tum', 'Shredded unripe papaya tossed with tomatoes, green beans, peanuts, chili, and lime in a tangy, spicy fish sauce dressing.', FALSE, 'https://commons.wikimedia.org/wiki/Special:FilePath/Som%20Tam%20green%20papaya%20salad%2C%20Bangkok%2C%20Thailand.jpg?width=480', 'Bowl of shredded green papaya salad'),
  ('Massaman Curry', 'A rich, mildly spiced curry with beef, potato, and onion, simmered in coconut milk and topped with roasted peanuts.', TRUE, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaeng_matsaman_kai.JPG?width=480', 'Bowl of massaman curry with beef and potato'),
  ('Pad Thai', 'Stir-fried rice noodles with shrimp, egg, and tofu in a sweet-and-sour tamarind sauce, topped with crushed peanuts and lime.', FALSE, 'https://commons.wikimedia.org/wiki/Special:FilePath/Phat_Thai_kung_Chang_Khien_street_stall.jpg?width=480', 'Plate of pad thai noodles with shrimp and lime'),
  ('Khao Soi', 'A Northern Thai curry noodle soup with tender chicken, coconut broth, and crispy fried egg noodles, served with pickled greens.', TRUE, 'https://commons.wikimedia.org/wiki/Special:FilePath/Khao_Soi_Northern_Thai_food_%E0%B8%82%E0%B9%89%E0%B8%B2%E0%B8%A7%E0%B8%8B%E0%B8%AD%E0%B8%A2_%E0%B8%9C%E0%B8%B1%E0%B8%81%E0%B8%94%E0%B8%AD%E0%B8%87.jpg?width=480', 'Bowl of khao soi curry noodle soup with crispy noodles');
